INSERT INTO public.site_content
  (section, slug, title, category, date_label, excerpt, body, image_url, image_alt, media_type, published)
VALUES
('berita', 'spektakuler-bertumbuh-berkarya', 'SPECTACULAR: Bertumbuh, Berkarya, dan Menginspirasi', 'Kegiatan sekolah', 'Kabar sekolah', 'Ruang belajar yang baik memberi kesempatan bagi siswa untuk bertanya, bekerja sama, dan mengembangkan potensi.', $json$["Sekolah merupakan ruang untuk belajar sekaligus membangun karakter. Dalam keseharian di lingkungan sekolah, siswa mendapatkan kesempatan untuk bertukar gagasan, belajar menghargai perbedaan, dan mengembangkan rasa tanggung jawab.", "Semangat SPECTACULAR mengajak siswa untuk terus bertumbuh dalam kecerdasan, ketangguhan, kreativitas, bakat, wawasan budaya, dan karakter. Nilai-nilai tersebut dapat dihidupi melalui proses pembelajaran maupun kegiatan di luar kelas.", "Halaman berita ini dirancang sebagai tempat publikasi kegiatan sekolah. Untuk penerbitan resmi, isi artikel perlu dilengkapi tanggal, nama kegiatan, dokumentasi, dan keterangan yang telah dikonfirmasi oleh pihak sekolah."]$json$::jsonb, '/images/gedung-utama.png', 'Kegiatan siswa di aula SMAN 3 Semarang', 'image', true),
('berita', 'mengenal-lingkungan-sekolah', 'Mengenal Lingkungan dan Ruang Belajar SMAN 3 Semarang', 'Lingkungan', 'Profil sekolah', 'Lingkungan sekolah menjadi bagian penting dari pengalaman belajar, kebersamaan, dan pembentukan kebiasaan baik.', $json$["Lingkungan sekolah bukan hanya kumpulan ruang dan bangunan. Di dalamnya, siswa membangun kebiasaan, menjalin pertemanan, dan belajar menjadi bagian dari komunitas yang saling menghargai.", "Ruang yang tertata, lingkungan yang dijaga bersama, serta komunikasi yang baik membantu kegiatan pendidikan berlangsung dengan nyaman. Perawatan fasilitas juga merupakan bentuk tanggung jawab seluruh warga sekolah.", "Informasi detail mengenai fasilitas, jam akses, dan aturan penggunaan perlu mengikuti ketentuan terbaru yang ditetapkan sekolah."]$json$::jsonb, '/images/ruang.jpg', 'Area lingkungan sekolah SMAN 3 Semarang', 'image', true),
('berita', 'belajar-melalui-kolaborasi', 'Belajar Lebih Jauh melalui Kolaborasi', 'Pembelajaran', 'Inspirasi belajar', 'Diskusi, kerja kelompok, dan keberanian menyampaikan pendapat membantu siswa mengembangkan cara berpikir.', $json$["Belajar tidak hanya berarti mengingat informasi. Siswa juga perlu berlatih mengajukan pertanyaan, menyusun argumen, mendengarkan sudut pandang berbeda, dan bekerja bersama untuk menyelesaikan persoalan.", "Kolaborasi yang sehat memberi ruang bagi setiap anggota untuk berkontribusi. Perbedaan kemampuan dan ide dapat menjadi kekuatan ketika semua pihak saling menghargai dan berfokus pada tujuan bersama.", "Guru dan lingkungan sekolah berperan dalam menciptakan proses belajar yang mendorong rasa ingin tahu, kemandirian, dan tanggung jawab."]$json$::jsonb, '/images/kegiatan-sekolah.png', 'Gedung utama SMA Negeri 3 Semarang', 'image', true),
('berita', 'mengembangkan-minat-bakat', 'Mengembangkan Minat dan Bakat di Luar Kelas', 'Kesiswaan', 'Pengembangan diri', 'Kegiatan pengembangan diri memberi kesempatan untuk mencoba hal baru dan melatih tanggung jawab.', $json$["Setiap siswa memiliki minat dan potensi yang dapat dikembangkan melalui pengalaman yang beragam. Kegiatan di luar pembelajaran kelas dapat menjadi tempat untuk belajar mengatur waktu, berkomunikasi, dan bekerja sama.", "Saat terlibat dalam kegiatan bersama, siswa berlatih menyusun rencana, menjalankan peran, menghadapi tantangan, serta mengevaluasi proses yang telah dilakukan. Pengalaman tersebut menjadi bagian dari pembentukan karakter.", "Daftar kegiatan aktif, jadwal, dan mekanisme pendaftaran sebaiknya merujuk pada informasi terbaru dari sekolah dan pembina masing-masing kegiatan."]$json$::jsonb, '/images/minat.jpeg', 'Siswa mengikuti kegiatan bersama di aula sekolah', 'image', true),
('berita', 'membangun-budaya-literasi', 'Membangun Budaya Literasi dan Rasa Ingin Tahu', 'Akademik', 'Inspirasi belajar', 'Kebiasaan membaca, meneliti, dan memeriksa informasi menjadi bekal menghadapi dunia yang terus berubah.', $json$["Literasi membantu siswa memahami informasi, memilah sumber, dan menyampaikan gagasan dengan lebih jernih. Kebiasaan membaca dapat diperkuat melalui diskusi, pencatatan ide, dan eksplorasi topik yang relevan.", "Rasa ingin tahu juga perlu diikuti kemampuan memeriksa bukti. Ketika menemukan informasi baru, siswa dapat membandingkan sumber, mencari konteks, dan membedakan fakta dari pendapat.", "Budaya literasi akan berkembang ketika dilakukan secara konsisten dan didukung lingkungan yang menyediakan kesempatan untuk bertanya serta berbagi pengetahuan."]$json$::jsonb, '/images/baca.webp', 'Area sekolah yang mendukung aktivitas belajar', 'image', true),
('berita', 'merawat-lingkungan-bersama', 'Merawat Lingkungan Sekolah sebagai Tanggung Jawab Bersama', 'Lingkungan', 'Kehidupan sekolah', 'Kebiasaan sederhana menjaga kebersihan membantu membentuk lingkungan belajar yang nyaman.', $json$["Lingkungan belajar yang nyaman membutuhkan partisipasi seluruh warga sekolah. Menjaga kebersihan, menggunakan fasilitas dengan baik, dan membuang sampah pada tempatnya adalah kebiasaan sederhana yang berdampak nyata.", "Kepedulian tidak harus dimulai dari program besar. Kebiasaan sehari-hari yang dilakukan bersama dapat menumbuhkan rasa memiliki dan tanggung jawab terhadap ruang publik.", "Program kebersihan atau lingkungan yang berlangsung pada waktu tertentu dapat dipublikasikan melalui halaman ini setelah detail kegiatan dikonfirmasi oleh pihak sekolah."]$json$::jsonb, '/images/rawat.jpeg', 'Bagian depan gedung SMA Negeri 3 Semarang', 'image', true),
('berita', 'prestasi-dan-proses', 'Menghargai Proses di Balik Setiap Prestasi', 'Prestasi', 'Pengembangan diri', 'Prestasi tumbuh melalui latihan, konsistensi, dukungan, dan keberanian untuk terus memperbaiki diri.', $json$["Prestasi bukan hanya tentang hasil akhir. Di balik sebuah pencapaian terdapat proses berlatih, menerima masukan, memperbaiki strategi, dan bertahan saat menghadapi kesulitan.", "Lingkungan sekolah dapat membantu siswa mengenali kekuatan sekaligus area yang perlu dikembangkan. Apresiasi terhadap proses mendorong siswa untuk terus belajar tanpa mengabaikan integritas dan sikap sportif.", "Nama kompetisi, peserta, peringkat, dan tanggal pencapaian perlu diisi berdasarkan pengumuman atau dokumentasi resmi agar informasi yang ditampilkan akurat."]$json$::jsonb, '/images/proses.jpg', 'Suasana kegiatan siswa di sekolah', 'image', true),
('berita', 'sains-teknologi-dan-kreativitas', 'Sains, Teknologi, dan Kreativitas untuk Masa Depan', 'Akademik', 'Inspirasi belajar', 'Berpikir kritis dan kreatif membantu siswa menghadapi persoalan dengan pendekatan yang bertanggung jawab.', $json$["Sains dan teknologi memberi banyak cara untuk memahami masalah serta menguji kemungkinan solusi. Proses tersebut membutuhkan ketelitian, rasa ingin tahu, dan kemauan untuk memeriksa hasil.", "Kreativitas membantu siswa menghubungkan pengetahuan dengan kebutuhan nyata. Ide yang baik tidak hanya menarik, tetapi juga mempertimbangkan manfaat, keamanan, dan dampaknya bagi orang lain.", "Kegiatan proyek, praktikum, dan eksplorasi teknologi dapat menjadi bagian dari pembelajaran yang lebih aktif ketika dilaksanakan sesuai program sekolah."]$json$::jsonb, '/images/sains.jpg', 'Gedung sekolah sebagai ruang belajar', 'image', true),
('berita', 'karakter-dan-kebersamaan', 'Karakter Tumbuh melalui Kebersamaan', 'Karakter', 'Kehidupan sekolah', 'Sikap saling menghormati, disiplin, dan peduli dibangun lewat pilihan-pilihan sehari-hari.', $json$["Karakter terbentuk melalui tindakan yang dilakukan berulang kali. Menghormati orang lain, menepati kesepakatan, dan bertanggung jawab terhadap tugas merupakan contoh kebiasaan yang penting dalam kehidupan sekolah.", "Kebersamaan yang sehat bukan berarti semua orang harus sama. Setiap siswa dapat belajar menerima perbedaan, menyampaikan pendapat dengan santun, dan mencari penyelesaian ketika muncul konflik.", "Nilai karakter perlu diperkuat melalui keteladanan, aturan yang jelas, serta komunikasi yang konsisten antara seluruh warga sekolah."]$json$::jsonb, '/images/sri-sma3.jpg', 'Koridor dan lingkungan sekolah', 'image', true),
('berita', 'sekolah-ruang-untuk-bertumbuh', 'Sekolah sebagai Ruang untuk Bertumbuh dan Berkontribusi', 'Inspirasi', 'Profil sekolah', 'Pendidikan mempersiapkan siswa untuk terus belajar, mengambil keputusan, dan berkontribusi bagi masyarakat.', $json$["Pendidikan merupakan perjalanan yang membantu siswa mengenali diri, memperluas wawasan, dan mempersiapkan langkah berikutnya. Setiap pengalaman belajar dapat menjadi kesempatan untuk bertumbuh.", "Selain pengetahuan, siswa membutuhkan kemampuan berkomunikasi, bekerja sama, berpikir kritis, dan menggunakan teknologi secara bertanggung jawab. Kemampuan tersebut berkembang melalui latihan dan refleksi.", "Website ini menyediakan struktur informasi yang dapat dikembangkan untuk menampilkan kabar sekolah, program, prestasi, galeri, serta informasi layanan kepada siswa dan orang tua."]$json$::jsonb, '/images/siswa.jpg', 'Tampak depan gedung SMAN 3 Semarang', 'image', true)
