-- Pemulihan konten berita lama dari src/data/news.js ke Supabase.
-- Aman dijalankan ulang: slug yang sudah ada tidak ditimpa.
-- Jalankan setelah tabel public.site_content tersedia.

ON CONFLICT (slug) DO NOTHING;

-- Verifikasi jumlah berita:
SELECT section, count(*) AS total, count(*) FILTER (WHERE published) AS published
FROM public.site_content
GROUP BY section
ORDER BY section;
